String money(int paise) => '₹${(paise/100).toStringAsFixed(2)}';
String tr(bool bn, String en, String be) => bn ? be : en;

class LoginScreen extends StatefulWidget {
  final bool bengali; final VoidCallback onLanguage;
  const LoginScreen({super.key,required this.bengali,required this.onLanguage});
  @override State<LoginScreen> createState()=>_LoginScreenState();
}
class _LoginScreenState extends State<LoginScreen> {
  final pin=TextEditingController(); String? error; bool setup=false;
  @override void initState(){super.initState(); _check();}
  Future<void> _check() async { final p=await SharedPreferences.getInstance(); if(mounted)setState(()=>setup=p.getString('admin_pin_hash')==null); }
  Future<void> _submit() async { final p=await SharedPreferences.getInstance(); final value=pin.text.trim(); if(value.length<4){setState(()=>error=tr(widget.bengali,'Enter at least 4 digits','কমপক্ষে ৪ সংখ্যার PIN দিন'));return;} if(setup){await p.setString('admin_pin_hash',sha256.convert(utf8.encode(value)).toString()); if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomeScreen(bengali:widget.bengali,onLanguage:widget.onLanguage)));} else {final hash=sha256.convert(utf8.encode(value)).toString(); if(hash==p.getString('admin_pin_hash')){if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomeScreen(bengali:widget.bengali,onLanguage:widget.onLanguage)));}else setState(()=>error=tr(widget.bengali,'Incorrect PIN','PIN সঠিক নয়'));} }
  @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Column(mainAxisSize:MainAxisSize.min,children:[const CircleAvatar(radius:38,child:Icon(Icons.school,size:42)),const SizedBox(height:18),const Text('Peace Valley Radiant Mission',textAlign:TextAlign.center,style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(tr(widget.bengali,'School Management','স্কুল ম্যানেজমেন্ট')),const SizedBox(height:26),Text(setup?tr(widget.bengali,'Create Admin PIN','অ্যাডমিন PIN তৈরি করুন'):tr(widget.bengali,'Admin Login','অ্যাডমিন লগইন'),style:const TextStyle(fontSize:20)),const SizedBox(height:12),TextField(controller:pin,obscureText:true,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:tr(widget.bengali,'PIN / Password','PIN / পাসওয়ার্ড'),border:const OutlineInputBorder(),prefixIcon:const Icon(Icons.lock)),onSubmitted:(_)=>_submit()),if(error!=null)Padding(padding:const EdgeInsets.all(8),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:14),FilledButton(onPressed:_submit,child:Text(tr(widget.bengali,'Continue','চালিয়ে যান'))),TextButton(onPressed:widget.onLanguage,child:Text(widget.bengali?'English':'বাংলা')),const SizedBox(height:8),Text(tr(widget.bengali,'PIN is stored on this device. Remember it; recovery is not configured.','PIN এই ডিভাইসে সংরক্ষিত হবে। মনে রাখবেন; পুনরুদ্ধারের ব্যবস্থা নেই।'),textAlign:TextAlign.center,style:const TextStyle(fontSize:12,color:Colors.grey))])))));
}

class HomeScreen extends StatefulWidget { final bool bengali; final VoidCallback onLanguage; const HomeScreen({super.key,required this.bengali,required this.onLanguage}); @override State<HomeScreen> createState()=>_HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen>{int index=0; void refresh()=>setState((){}); @override Widget build(BuildContext context){final pages=[Dashboard(bn:widget.bengali),StudentsScreen(bn:widget.bengali),AttendanceScreen(bn:widget.bengali),FeesScreen(bn:widget.bengali),SalaryScreen(bn:widget.bengali),ReportsScreen(bn:widget.bengali),SyncScreen(bn:widget.bengali)]; final labels=widget.bengali?['হোম','শিক্ষার্থী','হাজিরা','ফি','বেতন','রিপোর্ট','সিঙ্ক']:['Home','Students','Attendance','Fees','Salary','Reports','Sync']; final icons=[Icons.dashboard,Icons.people,Icons.fact_check,Icons.payments,Icons.badge,Icons.bar_chart,Icons.sync]; return Scaffold(appBar:AppBar(title:const Text('Peace Valley Radiant Mission'),actions:[IconButton(onPressed:widget.onLanguage,icon:const Icon(Icons.translate)),IconButton(onPressed:()async{final p=await SharedPreferences.getInstance();await p.remove('admin_pin_hash');if(context.mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>LoginScreen(bengali:widget.bengali,onLanguage:widget.onLanguage)),(_)=>false);},icon:const Icon(Icons.lock))]),body:pages[index],bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:List.generate(labels.length,(i)=>NavigationDestination(icon:Icon(icons[i]),label:labels[i]))));}}

class Dashboard extends StatelessWidget{final bool bn;const Dashboard({super.key,required this.bn}); @override Widget build(BuildContext context)=>FutureBuilder<List<int>>(future:Future.wait([AppDb.instance.count('students'),AppDb.instance.count('teachers'),AppDb.instance.count('attendance'),AppDb.instance.total('fee_payments','amountPaise')]),builder:(c,s){final d=s.data??[0,0,0,0];return ListView(padding:const EdgeInsets.all(16),children:[Text(tr(bn,'Dashboard','ড্যাশবোর্ড'),style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:14),Wrap(spacing:12,runSpacing:12,children:[_stat(tr(bn,'Students','শিক্ষার্থী'),d[0],Icons.people),_stat(tr(bn,'Teachers','শিক্ষক'),d[1],Icons.badge),_stat(tr(bn,'Attendance entries','হাজিরা'),d[2],Icons.fact_check),_stat(tr(bn,'Fees collected','মোট ফি'),d[3]~/100,Icons.payments)]),const SizedBox(height:20),Text(tr(bn,'Choose a section from the bottom menu. Data is stored on this device.','নিচের মেনু থেকে বিভাগ নির্বাচন করুন। তথ্য এই ডিভাইসে সংরক্ষিত হয়।'))]);});}
Widget _stat(String title,int value,IconData icon)=>SizedBox(width:155,child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,size:28),const SizedBox(height:12),Text('$value',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),Text(title)]))));

class StudentsScreen extends StatefulWidget{final bool bn;const StudentsScreen({super.key,required this.bn});@override State<StudentsScreen> createState()=>_StudentsScreenState();}
class _StudentsScreenState extends State<StudentsScreen>{Future<void> add()async{final name=TextEditingController(),cls=TextEditingController(),guardian=TextEditingController(),phone=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(tr(widget.bn,'Add student','শিক্ষার্থী যোগ করুন')),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:InputDecoration(labelText:tr(widget.bn,'Student name','শিক্ষার্থীর নাম'))),TextField(controller:cls,decoration:InputDecoration(labelText:tr(widget.bn,'Class','শ্রেণি'))),TextField(controller:guardian,decoration:InputDecoration(labelText:tr(widget.bn,'Guardian','অভিভাবক'))),TextField(controller:phone,decoration:InputDecoration(labelText:tr(widget.bn,'Phone','ফোন')))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:Text(tr(widget.bn,'Cancel','বাতিল'))),FilledButton(onPressed:()=>Navigator.pop(c,true),child:Text(tr(widget.bn,'Save','সংরক্ষণ')))]));if(ok==true&&name.text.trim().isNotEmpty&&cls.text.trim().isNotEmpty){await AppDb.instance.addStudent(name.text.trim(),cls.text.trim(),guardian.text.trim(),phone.text.trim());setState((){});}}
@override Widget build(BuildContext context)=>Scaffold(body:FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.students(),builder:(c,s)=>ListView(children:[if((s.data??[]).isEmpty)Padding(padding:const EdgeInsets.all(24),child:Text(tr(widget.bn,'No students yet. Tap + to add.','এখনও শিক্ষার্থী নেই। + চাপুন।'))),...(s.data??[]).map((r)=>ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${r['name']}'),subtitle:Text('${r['className']} • ${r['guardian']??''}'),trailing:Text('#${r['id']}')))])),floatingActionButton:FloatingActionButton(onPressed:add,child:const Icon(Icons.add)));}}

class AttendanceScreen extends StatefulWidget{final bool bn;const AttendanceScreen({super.key,required this.bn});@override State<AttendanceScreen> createState()=>_AttendanceScreenState();}
class _AttendanceScreenState extends State<AttendanceScreen>{@override Widget build(BuildContext context)=>FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.students(),builder:(c,s)=>ListView(padding:const EdgeInsets.all(8),children:[Padding(padding:const EdgeInsets.all(12),child:Text(tr(widget.bn,'Mark today’s attendance','আজকের হাজিরা নিন'),style:Theme.of(context).textTheme.titleLarge)),...(s.data??[]).map((r)=>ListTile(title:Text('${r['name']}'),subtitle:Text('${r['className']}'),trailing:Wrap(children:[IconButton(tooltip:'Present',icon:const Icon(Icons.check_circle,color:Colors.green),onPressed:()async{await AppDb.instance.markAttendance(r['id'] as int,'Present');if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tr(widget.bn,'Marked present','উপস্থিত হিসেবে চিহ্নিত'))));}),IconButton(tooltip:'Absent',icon:const Icon(Icons.cancel,color:Colors.red),onPressed:()async{await AppDb.instance.markAttendance(r['id'] as int,'Absent');if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tr(widget.bn,'Marked absent','অনুপস্থিত হিসেবে চিহ্নিত'))));})])))]));}

class FeesScreen extends StatefulWidget{final bool bn;const FeesScreen({super.key,required this.bn});@override State<FeesScreen> createState()=>_FeesScreenState();}
class _FeesScreenState extends State<FeesScreen>{Future<void> collect()async{final students=await AppDb.instance.students();if(!mounted)return;if(students.isEmpty){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tr(widget.bn,'Add a student first','আগে শিক্ষার্থী যোগ করুন'))));return;}int id=students.first['id'] as int;final amount=TextEditingController(),purpose=TextEditingController(text:'Monthly fee');final receipt=await showDialog<String>(context:context,builder:(c)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:Text(tr(widget.bn,'Collect fee','ফি সংগ্রহ')),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButton<int>(isExpanded:true,value:id,items:students.map((s)=>DropdownMenuItem(value:s['id'] as int,child:Text('${s['name']} (${s['className']})'))).toList(),onChanged:(v){if(v!=null)set(()=>id=v);}),TextField(controller:amount,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:tr(widget.bn,'Amount in ₹','টাকার পরিমাণ'))),TextField(controller:purpose,decoration:InputDecoration(labelText:tr(widget.bn,'Purpose','কিসের ফি')))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(tr(widget.bn,'Cancel','বাতিল'))),FilledButton(onPressed:(){final a=double.tryParse(amount.text);if(a!=null&&a>0)Navigator.pop(c,'$id|${(a*100).round()}|${purpose.text}');},child:Text(tr(widget.bn,'Save & receipt','সংরক্ষণ ও রসিদ')))])));if(receipt!=null){final p=receipt.split('|');final no=await AppDb.instance.addFee(int.parse(p[0]),int.parse(p[1]),p[2]);final row=await AppDb.instance.feeByReceipt(no);if(row!=null)await makeReceipt(row);if(mounted)setState((){});}}
@override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.all(16),child:FilledButton.icon(onPressed:collect,icon:const Icon(Icons.add),label:Text(tr(widget.bn,'Collect fee','ফি জমা নিন')))),Expanded(child:FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.database.then((db)=>db.rawQuery('SELECT fee_payments.*, students.name AS studentName FROM fee_payments JOIN students ON students.id=fee_payments.studentId ORDER BY fee_payments.id DESC')),builder:(c,s)=>ListView(children:[...(s.data??[]).map((r)=>ListTile(title:Text('${r['studentName']} — ${money(r['amountPaise'] as int)}'),subtitle:Text('${r['receiptNo']} • ${r['purpose']}'),trailing:IconButton(icon:const Icon(Icons.picture_as_pdf),onPressed:()=>makeReceipt(r))))])))]);}
Future<void> makeReceipt(Map<String,Object?> r)async{final doc=pw.Document();doc.addPage(pw.Page(build:(ctx)=>pw.Padding(padding:const pw.EdgeInsets.all(24),child:pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text('Peace Valley Radiant Mission',style:pw.TextStyle(fontSize:20,fontWeight:pw.FontWeight.bold)),pw.SizedBox(height:20),pw.Text('FEE RECEIPT'),pw.Divider(),pw.Text('Receipt: ${r['receiptNo']}'),pw.Text('Student: ${r['studentName']}'),pw.Text('Class: ${r['className']??'-'}'),pw.Text('Purpose: ${r['purpose']}'),pw.Text('Amount: ${money(r['amountPaise'] as int)}'),pw.Text('Date: ${r['paidAt']}'),pw.SizedBox(height:40),pw.Text('Authorized signature: __________________')])));await Printing.layoutPdf(onLayout:(_)=>doc.save());}

